双指针：左指针 l 从头、右指针 r 从尾。a[l]+a[r] 等于 t 则计数并同时内收；小于 t 则左移 l（需更大值）；大于 t 则右移 r（需更小值）。数组严格升序故每对唯一。时间复杂度 O(n)。参考程序：

```cpp
#include <iostream>
using namespace std;

typedef long long ll;
ll a[100005];

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    int n; ll t;
    cin >> n >> t;
    for (int i = 0; i < n; i++) cin >> a[i];
    int l = 0, r = n - 1;
    ll ans = 0;
    while (l < r) {
        ll s = a[l] + a[r];
        if (s == t) { ans++; l++; r--; }
        else if (s < t) l++;
        else r--;
    }
    cout << ans << "\n";
    return 0;
}
```

用结构体存学号与三科成绩，计算总分。按"总分降序、语文降序、学号升序"自定义比较函数传给 sort。时间复杂度 O(n log n)。参考程序：

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

struct Stu {
    int id, a, b, c, sum;
};

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    int n; cin >> n;
    vector<Stu> v(n);
    for (int i = 0; i < n; i++) {
        cin >> v[i].id >> v[i].a >> v[i].b >> v[i].c;
        v[i].sum = v[i].a + v[i].b + v[i].c;
    }
    sort(v.begin(), v.end(), [](const Stu& x, const Stu& y) {
        if (x.sum != y.sum) return x.sum > y.sum;
        if (x.a != y.a) return x.a > y.a;
        return x.id < y.id;
    });
    for (auto& s : v) cout << s.id << " " << s.sum << "\n";
    return 0;
}
```

二分查找 0~n 中最大的 mid 使得 mid²≤n。注意用 long long 防溢出。

参考程序：

```cpp
#include <iostream>
using namespace std;

typedef long long ll;

int main()
{
    ll n;
    cin >> n;
    ll l = 0, r = n, ans = 0;
    while (l <= r)
    {
        ll mid = l + (r - l) / 2;
        if (mid <= n / mid) { ans = mid; l = mid + 1; }
        else r = mid - 1;
    }
    cout << ans << endl;
    return 0;
}
```

map 统计票数，将 map 中的 pair 转入 vector，按票数降序、名字字典序升序排序后输出。

参考程序：

```cpp
#include <iostream>
#include <map>
#include <vector>
#include <algorithm>
#include <string>
using namespace std;

int main()
{
    int n;
    string s;
    map<string,int> mp;
    cin >> n;
    for (int i = 0; i < n; i++) { cin >> s; mp[s]++; }
    vector<pair<int,string>> v;
    for (auto &p : mp) v.push_back({-p.second, p.first});
    sort(v.begin(), v.end());
    for (auto &p : v) cout << p.second << " " << -p.first << endl;
    return 0;
}
```
